// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address recipient;

    function setUp() public {
        c = new C(address(this));
        recipient = address(0xdead);
        // Deploy a contract at recipient that reverts on receive
        vm.etch(recipient, type(EvilRecipient).runtimeCode);
    }

    function testRegression_property() public {
        vm.deal(address(c), 1 ether);
        vm.prank(address(this));
        // This call to withdrawAll should succeed for reference (transfer) and fail for buggy (send)
        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        // After the call, reference has balance 0 (transfer succeeded); buggy leaves balance non-zero (send failed)
        assertTrue(ok ? address(c).balance == 0 : address(c).balance > 0);
    }
}

contract EvilRecipient {
    fallback() external payable {
        revert("no ether");
    }
    receive() external payable {
        revert("no ether");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Deploy a recipient that uses >2300 gas in fallback
        RecipientGreedy recip = new RecipientGreedy();
        // Fund the C contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Owner is address(this)
        vm.prank(address(this));
        c.withdrawAll(address(recip));
        // Reference: transfer succeeds -> c.balance becomes 0
        // Bug: send fails -> c.balance remains 1 ether
        assertTrue(address(c).balance == 0);
    }
}

contract RecipientGreedy {
    fallback() external payable {
        // Use more than 2300 gas to cause send to fail
        uint256 x;
        for (uint256 i = 0; i < 100; i++) {
            x += i;
        }
    }
}

