pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address recipient = address(0xDead);
        vm.deal(address(c), 1 wei);
        uint256 balanceBefore = address(recipient).balance;
        c.withdrawAll(recipient);
        // Reference sends to recipient, bug sends to msg.sender
        bool recipientGotPaid = (address(recipient).balance == balanceBefore + 1 wei);
        assertTrue(recipientGotPaid);
    }
}
